alter type "public"."app_permission" rename to "app_permission__old_version_to_be_dropped";

create type "public"."app_permission" as enum ('products.delete', 'orders.delete', 'products.create', 'products.read', 'products.update', 'AR.create', 'AR.read', 'AR.update', 'AR.delete');

create table "public"."ARCollectible" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "name" text,
    "image" text
);


alter table "public"."ARCollectible" enable row level security;

create table "public"."orders" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now()
);


alter table "public"."orders" enable row level security;

create table "public"."reviews" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "rating" integer,
    "comment" text,
    "product_id" bigint
);


alter table "public"."reviews" enable row level security;

alter table "public"."role_permissions" alter column permission type "public"."app_permission" using permission::text::"public"."app_permission";

drop type "public"."app_permission__old_version_to_be_dropped";

alter table "public"."products" add column "category" text;

alter table "public"."products" add column "images" text;

alter table "public"."products" add column "review_id" bigint;

alter table "public"."user_roles" alter column "role" drop not null;

CREATE UNIQUE INDEX "ARCollectible_pkey" ON public."ARCollectible" USING btree (id);

CREATE UNIQUE INDEX orders_pkey ON public.orders USING btree (id);

CREATE UNIQUE INDEX reviews_pkey ON public.reviews USING btree (id);

alter table "public"."ARCollectible" add constraint "ARCollectible_pkey" PRIMARY KEY using index "ARCollectible_pkey";

alter table "public"."orders" add constraint "orders_pkey" PRIMARY KEY using index "orders_pkey";

alter table "public"."reviews" add constraint "reviews_pkey" PRIMARY KEY using index "reviews_pkey";

alter table "public"."products" add constraint "products_review_id_fkey" FOREIGN KEY (review_id) REFERENCES reviews(id) ON UPDATE CASCADE ON DELETE SET NULL not valid;

alter table "public"."products" validate constraint "products_review_id_fkey";

alter table "public"."reviews" add constraint "reviews_product_id_fkey" FOREIGN KEY (product_id) REFERENCES products(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;

alter table "public"."reviews" validate constraint "reviews_product_id_fkey";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.custom_access_token_hook(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$declare
    claims jsonb;
    user_role public.app_role;
  begin
    -- Fetch the user role in the user_roles table using LEFT JOIN
    select ur.role into user_role
    from public.user_roles ur
    where ur.user_id = (event->>'user_id')::uuid;

    claims := event->'claims';

    if user_role is not null then
        -- Set the claim
        claims := jsonb_set(claims, '{user_role}', to_jsonb(user_role));
    else
        claims := jsonb_set(claims, '{user_role}', '"customer"');
    end if;

    -- Update the 'claims' object in the original event
    event := jsonb_set(event, '{claims}', claims);

    -- Return the modified or original event
    return event;
  end;$function$
;

