create policy "Add authorized delete"
on "public"."ARCollectible"
as permissive
for delete
to authenticated
using (authorize('AR.delete'::app_permission));


create policy "Add authorized update"
on "public"."ARCollectible"
as permissive
for update
to authenticated
using (authorize('AR.update'::app_permission));


create policy "Allow authorized create"
on "public"."ARCollectible"
as permissive
for insert
to authenticated
with check (authorize('AR.create'::app_permission));


create policy "Enable read access for authenticated users"
on "public"."ARCollectible"
as permissive
for select
to authenticated
using (true);



